list_discount_profiles.code:
var response = await client.DiscountProfiles.ListDiscountProfilesAsync(
    new Dictionary<string, object?> { ["sort"] = "name", ["dir"] = "asc" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var discountProfile in ((IReadOnlyList<object?>)body["discount_profiles"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{discountProfile["id"]} {discountProfile["name"]} {discountProfile["type"]} {discountProfile["is_active"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

